from pathlib import Path

path = Path("/opt/astral/api/src/server.js")
text = path.read_text()

backup = Path("/opt/astral/api/src/server.js.bak-before-global-mirror")
if not backup.exists():
    backup.write_text(text)
    print("OK : sauvegarde global-mirror créée.")
else:
    print("OK : sauvegarde global-mirror déjà présente.")

required = [
    '/v1/daily-gift/claim',
    '/v1/global-gifts/claim',
    'const makeHttpError =',
]
missing = [item for item in required if item not in text]
if missing:
    raise SystemExit(
        "ERREUR : fondation VPS incomplète, aucune modification. Manque : "
        + ", ".join(missing)
    )

HELPERS = 'const snapshotSyncMs = (snapshot) => {\n  if (!snapshot || typeof snapshot !== "object" || Array.isArray(snapshot)) return 0;\n  for (const value of [\n    snapshot.synced_at,\n    snapshot.last_active_at,\n    snapshot.updated_at,\n    snapshot.created_at,\n  ]) {\n    const parsed = Date.parse(String(value || ""));\n    if (Number.isFinite(parsed) && parsed > 0) return parsed;\n  }\n  return 0;\n};\n\nconst mirrorSnapshot = (raw) => {\n  const snapshot = cloneSnapshot(raw);\n  for (const key of Object.keys(snapshot)) {\n    if (key.startsWith("_vps_")) delete snapshot[key];\n  }\n  return snapshot;\n};\n\nconst normalizeMirrorEmail = (value) => {\n  const email = String(value || "").trim().toLowerCase().slice(0, 254);\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email) ? email : "";\n};\n\n'
if "const snapshotSyncMs =" not in text:
    anchor = "const makeHttpError ="
    text = text.replace(anchor, HELPERS + anchor, 1)
    print("OK : helpers miroir villages ajoutés.")
else:
    print("OK : helpers miroir déjà présents.")

ROUTES = 'app.post("/v1/village/mirror", { preHandler: requireAstraAuth }, async (request, reply) => {\n  const user = request.astraUser;\n  const snapshot = mirrorSnapshot(request.body?.snapshot);\n\n  if (!snapshot || !Object.keys(snapshot).length) {\n    return reply.code(400).send({\n      ok: false,\n      error: "Snapshot de village invalide.",\n    });\n  }\n\n  const client = await pool.connect();\n  try {\n    await client.query("BEGIN");\n    await client.query(\n      "SELECT pg_advisory_xact_lock(hashtext($1))",\n      [user.email],\n    );\n\n    const current = await client.query(\n      `SELECT revision, snapshot\n         FROM astra_villages\n        WHERE user_email = $1\n        FOR UPDATE`,\n      [user.email],\n    );\n\n    const revision = current.rowCount\n      ? Number(current.rows[0].revision || 0)\n      : 0;\n    const currentSnapshot = current.rowCount\n      ? cloneSnapshot(current.rows[0].snapshot)\n      : null;\n\n    const incomingMs = snapshotSyncMs(snapshot);\n    const currentMs = snapshotSyncMs(currentSnapshot);\n\n    if (\n      current.rowCount &&\n      incomingMs > 0 &&\n      currentMs > 0 &&\n      incomingMs + 1500 < currentMs\n    ) {\n      await client.query("COMMIT");\n      return {\n        ok: true,\n        mirrored: false,\n        skipped_stale: true,\n        revision,\n        source: "vps",\n      };\n    }\n\n    await client.query(\n      `INSERT INTO astra_players (user_email, user_id, display_name, updated_at)\n       VALUES ($1, $2, $3, NOW())\n       ON CONFLICT (user_email)\n       DO UPDATE SET\n         user_id = EXCLUDED.user_id,\n         display_name = EXCLUDED.display_name,\n         updated_at = NOW()`,\n      [user.email, user.userId, user.name],\n    );\n\n    const nextRevision = revision + 1;\n\n    await client.query(\n      `INSERT INTO astra_villages (user_email, revision, snapshot, updated_at)\n       VALUES ($1, $2, $3::jsonb, NOW())\n       ON CONFLICT (user_email)\n       DO UPDATE SET\n         revision = EXCLUDED.revision,\n         snapshot = EXCLUDED.snapshot,\n         updated_at = NOW()`,\n      [user.email, nextRevision, JSON.stringify(snapshot)],\n    );\n\n    await client.query("COMMIT");\n\n    return {\n      ok: true,\n      mirrored: true,\n      skipped_stale: false,\n      revision: nextRevision,\n      updated_at: new Date().toISOString(),\n      source: "vps",\n    };\n  } catch (error) {\n    await client.query("ROLLBACK").catch(() => null);\n    throw error;\n  } finally {\n    client.release();\n  }\n});\n\napp.get("/v1/admin/villages/status", { preHandler: requireAstraAuth }, async (request, reply) => {\n  if (!isAstraAdminUser(request.astraUser)) {\n    return reply.code(403).send({\n      ok: false,\n      error: "Accès administrateur refusé.",\n    });\n  }\n\n  const [counts, bootstrap] = await Promise.all([\n    pool.query(\n      `SELECT\n         COUNT(*)::int AS total,\n         COUNT(*) FILTER (WHERE updated_at >= NOW() - INTERVAL \'24 hours\')::int AS fresh_24h,\n         COUNT(*) FILTER (WHERE updated_at >= NOW() - INTERVAL \'1 hour\')::int AS fresh_1h\n       FROM astra_villages`,\n    ),\n    pool.query(\n      `SELECT value, updated_at\n         FROM astra_settings\n        WHERE setting_key = \'astra_village_bootstrap\'\n        LIMIT 1`,\n    ),\n  ]);\n\n  return {\n    ok: true,\n    total: Number(counts.rows?.[0]?.total || 0),\n    fresh_24h: Number(counts.rows?.[0]?.fresh_24h || 0),\n    fresh_1h: Number(counts.rows?.[0]?.fresh_1h || 0),\n    bootstrap: bootstrap.rows?.[0]?.value || null,\n    bootstrap_updated_at: bootstrap.rows?.[0]?.updated_at || null,\n    source: "vps",\n  };\n});\n\napp.post(\n  "/v1/admin/villages/import",\n  { preHandler: requireAstraAuth, bodyLimit: 4 * 1024 * 1024 },\n  async (request, reply) => {\n  if (!isAstraAdminUser(request.astraUser)) {\n    return reply.code(403).send({\n      ok: false,\n      error: "Accès administrateur refusé.",\n    });\n  }\n\n  const entries = (Array.isArray(request.body?.entries) ? request.body.entries : [])\n    .filter((entry) => entry && typeof entry === "object" && !Array.isArray(entry))\n    .slice(0, 4);\n  const finalBatch = request.body?.final === true;\n  const expectedTotal = clampInt(request.body?.expected_total || 0, 0, 5000);\n\n  let imported = 0;\n  let updated = 0;\n  let skipped = 0;\n  let stale = 0;\n\n  const client = await pool.connect();\n  try {\n    await client.query("BEGIN");\n\n    for (const entry of entries) {\n      const email = normalizeMirrorEmail(entry.email);\n      const snapshot = mirrorSnapshot(entry.snapshot);\n\n      if (!email || !Object.keys(snapshot).length) {\n        skipped += 1;\n        continue;\n      }\n\n      if (email === ASTRA_ADMIN_EMAIL) {\n        skipped += 1;\n        continue;\n      }\n\n      await client.query(\n        "SELECT pg_advisory_xact_lock(hashtext($1))",\n        [email],\n      );\n\n      const current = await client.query(\n        `SELECT revision, snapshot\n           FROM astra_villages\n          WHERE user_email = $1\n          FOR UPDATE`,\n        [email],\n      );\n\n      const revision = current.rowCount\n        ? Number(current.rows[0].revision || 0)\n        : 0;\n      const currentSnapshot = current.rowCount\n        ? cloneSnapshot(current.rows[0].snapshot)\n        : null;\n      const incomingMs = snapshotSyncMs(snapshot);\n      const currentMs = snapshotSyncMs(currentSnapshot);\n\n      if (\n        current.rowCount &&\n        incomingMs > 0 &&\n        currentMs > 0 &&\n        incomingMs + 1500 < currentMs\n      ) {\n        stale += 1;\n        continue;\n      }\n\n      const displayName =\n        String(entry.display_name || snapshot.user_name || email.split("@")[0] || "Joueur ASTRAL")\n          .trim()\n          .slice(0, 160) || "Joueur ASTRAL";\n\n      await client.query(\n        `INSERT INTO astra_players (user_email, user_id, display_name, updated_at)\n         VALUES ($1, $2, $3, NOW())\n         ON CONFLICT (user_email)\n         DO UPDATE SET\n           display_name = EXCLUDED.display_name,\n           updated_at = NOW()`,\n        [email, `base44:${email}`, displayName],\n      );\n\n      const nextRevision = revision + 1;\n      await client.query(\n        `INSERT INTO astra_villages (user_email, revision, snapshot, updated_at)\n         VALUES ($1, $2, $3::jsonb, NOW())\n         ON CONFLICT (user_email)\n         DO UPDATE SET\n           revision = EXCLUDED.revision,\n           snapshot = EXCLUDED.snapshot,\n           updated_at = NOW()`,\n        [email, nextRevision, JSON.stringify(snapshot)],\n      );\n\n      if (current.rowCount) updated += 1;\n      else imported += 1;\n\n      const sourceId = String(entry.source_id || snapshot.id || "").trim().slice(0, 180);\n      if (sourceId) {\n        await client.query(\n          `INSERT INTO astra_migration_log\n             (user_email, source, entity_name, source_id, imported_at, details)\n           VALUES ($1, \'base44\', \'AstraVillage\', $2, NOW(), $3::jsonb)\n           ON CONFLICT DO NOTHING`,\n          [\n            email,\n            sourceId,\n            JSON.stringify({\n              mirrored_at: new Date().toISOString(),\n              synced_at: snapshot.synced_at || null,\n            }),\n          ],\n        );\n      }\n    }\n\n    if (finalBatch) {\n      const completedAt = new Date().toISOString();\n      const value = {\n        completed_at: completedAt,\n        expected_total: expectedTotal,\n      };\n\n      await client.query(\n        `INSERT INTO astra_settings (setting_key, revision, value, updated_at)\n         VALUES (\'astra_village_bootstrap\', 1, $1::jsonb, NOW())\n         ON CONFLICT (setting_key)\n         DO UPDATE SET\n           revision = astra_settings.revision + 1,\n           value = EXCLUDED.value,\n           updated_at = NOW()`,\n        [JSON.stringify(value)],\n      );\n    }\n\n    await client.query("COMMIT");\n\n    return {\n      ok: true,\n      imported,\n      updated,\n      skipped,\n      stale,\n      received: entries.length,\n      final: finalBatch,\n      expected_total: expectedTotal,\n      source: "vps",\n    };\n  } catch (error) {\n    await client.query("ROLLBACK").catch(() => null);\n    throw error;\n  } finally {\n    client.release();\n  }\n  },\n);\n\n'
if "/v1/village/mirror" not in text:
    daily_pos = text.find("/v1/daily-gift/claim")
    route_start = text.rfind("app.post", 0, daily_pos)
    if daily_pos < 0 or route_start < 0:
        raise SystemExit("ERREUR : route daily-gift introuvable pour insertion.")
    text = text[:route_start] + ROUTES + text[route_start:]
    print("OK : routes miroir/import villages ajoutées.")
else:
    print("OK : routes miroir/import déjà présentes.")

ELIGIBILITY = '    const villageCreatedAt = Date.parse(\n      String(snapshot?.created_at || ""),\n    );\n    const giftPublishedAt = Date.parse(\n      String(gift.published_at || ""),\n    );\n    if (\n      Number.isFinite(villageCreatedAt) &&\n      Number.isFinite(giftPublishedAt) &&\n      villageCreatedAt > giftPublishedAt\n    ) {\n      throw makeHttpError(\n        404,\n        "Ce cadeau n’est pas disponible pour ce compte.",\n      );\n    }\n\n'
if "const villageCreatedAt = Date.parse(" not in text:
    claim_start = text.find("/v1/global-gifts/claim")
    if claim_start < 0:
        raise SystemExit("ERREUR : route global-gifts/claim introuvable.")
    marker = "    const existingResult = await client.query("
    marker_pos = text.find(marker, claim_start)
